(()=>{const b=document.querySelector('.navbutton'),n=document.querySelector('#navigation');if(b&&n)b.addEventListener('click',()=>{const o=n.classList.toggle('open');b.setAttribute('aria-expanded',String(o))});const s=document.querySelector('[data-language-select]');if(s)s.addEventListener('change',()=>{const q=location.search,h=location.hash;location.href=s.value+q+h});const f=document.querySelector('[data-card-search]'),g=document.querySelector('[data-card-grid]');if(f&&g)f.addEventListener('input',()=>{const q=f.value.trim().toLowerCase();g.querySelectorAll('[data-search]').forEach(c=>c.hidden=!c.dataset.search.includes(q))})})();